module SNPS_CLOCK_GATE_HIGH_PC_mydesign_0 ( CLK, EN, ENCLK );
  input CLK, EN;
  output ENCLK;
  wire   n1;

  TLATNXL latch ( .D(EN), .GN(CLK), .Q(n1) );
  AND2XL main_gate ( .A(n1), .B(CLK), .Y(ENCLK) );
endmodule


