module IF_stage ( clk, rst_n, boot_up, boot_addr, boot_datai, boot_web, 
        Branch_in, PCSrc, instn, PC_run, PC_add );
  input [7:0] boot_addr;
  input [31:0] boot_datai;
  input [15:0] Branch_in;
  output [31:0] instn;
  output [15:0] PC_add;
  input clk, rst_n, boot_up, boot_web, PCSrc;
  output PC_run;
  wire   icache_en_wr;
  wire   [7:0] icache_addr;

  PC PC ( .clk(clk), .rst_n(rst_n), .boot_up(boot_up), .PCSrc(PCSrc), .PC_out(
        PC_add), .PC_run(PC_run), .Branch_in(Branch_in) );
  dsram icache ( .addr(icache_addr), .clk(clk), .en_wr(icache_en_wr), .in(boot_datai), .out(instn) );
  // dsram_mydesign_1 icache ( .addr(icache_addr), .clk(clk), .en_wr(icache_en_wr), .in(boot_datai), .out(instn) );
  MX2XL U2 ( .A(boot_addr[6]), .B(PC_add[8]), .S0(PC_run), .Y(icache_addr[6])
         );
  MX2XL U3 ( .A(boot_addr[5]), .B(PC_add[7]), .S0(PC_run), .Y(icache_addr[5])
         );
  MX2XL U4 ( .A(boot_addr[4]), .B(PC_add[6]), .S0(PC_run), .Y(icache_addr[4])
         );
  MX2XL U5 ( .A(boot_addr[3]), .B(PC_add[5]), .S0(PC_run), .Y(icache_addr[3])
         );
  MX2XL U6 ( .A(boot_addr[2]), .B(PC_add[4]), .S0(PC_run), .Y(icache_addr[2])
         );
  MX2XL U7 ( .A(boot_addr[1]), .B(PC_add[3]), .S0(PC_run), .Y(icache_addr[1])
         );
  MX2XL U8 ( .A(boot_addr[0]), .B(PC_add[2]), .S0(PC_run), .Y(icache_addr[0])
         );
  MX2XL U9 ( .A(boot_addr[7]), .B(PC_add[9]), .S0(PC_run), .Y(icache_addr[7])
         );
  OR2XL U10 ( .A(PC_run), .B(boot_web), .Y(icache_en_wr) );
endmodule


module SNPS_CLOCK_GATE_HIGH_IF_ID_mydesign_0 ( CLK, EN, ENCLK );
  input CLK, EN;
  output ENCLK;
  wire   net7576;

  TLATNXL latch ( .D(EN), .GN(CLK), .Q(net7576) );
  AND2XL main_gate ( .A(net7576), .B(CLK), .Y(ENCLK) );
endmodule


module SNPS_CLOCK_GATE_HIGH_IF_ID_mydesign_1 ( CLK, EN, ENCLK );
  input CLK, EN;
  output ENCLK;
  wire   net7576;

  TLATNXL latch ( .D(EN), .GN(CLK), .Q(net7576) );
  AND2XL main_gate ( .A(net7576), .B(CLK), .Y(ENCLK) );
endmodule


module IF_ID ( clk, rst_n, IF_PC, instn, beq_enable, ID_PC, ID_instn );
  input [15:0] IF_PC;
