module controller ( opcode, RegDst, ALUOp, ALUSrc, branch, MemWrite, RegWrite, 
        MemtoReg, PCSrc, state, beq_enable, next_state, instn_31_, instn_30_, 
        instn_29_, instn_28_, instn_27_, instn_26_ );
  output [5:0] opcode;
  output [1:0] ALUOp;
  input [1:0] state;
  output [1:0] next_state;
  input PCSrc, instn_31_, instn_30_, instn_29_, instn_28_, instn_27_,
         instn_26_;
  output RegDst, ALUSrc, branch, MemWrite, RegWrite, MemtoReg, beq_enable;
  wire   n1, n2, n3, n4, n5, n6, n7, n8, n9, n10, n11;

  NOR4XL U3 ( .A(state[0]), .B(state[1]), .C(n5), .D(n4), .Y(next_state[0]) );
  NOR4BX1 U4 ( .AN(n8), .B(instn_28_), .C(instn_30_), .D(n7), .Y(n11) );
  INVXL U5 ( .A(instn_29_), .Y(n7) );
  NOR2XL U6 ( .A(n7), .B(n10), .Y(MemWrite) );
  NAND4XL U7 ( .A(n2), .B(instn_26_), .C(instn_27_), .D(instn_31_), .Y(n10) );
  BUFX2 U8 ( .A(instn_26_), .Y(opcode[0]) );
  BUFX2 U9 ( .A(instn_27_), .Y(opcode[1]) );
  BUFX2 U10 ( .A(instn_28_), .Y(opcode[2]) );
  BUFX2 U11 ( .A(instn_29_), .Y(opcode[3]) );
  BUFX2 U12 ( .A(instn_30_), .Y(opcode[4]) );
  BUFX2 U13 ( .A(instn_31_), .Y(opcode[5]) );
  INVXL U14 ( .A(instn_28_), .Y(n4) );
  NOR3XL U15 ( .A(instn_26_), .B(instn_27_), .C(instn_31_), .Y(n8) );
  NAND3BXL U16 ( .AN(instn_30_), .B(n8), .C(n7), .Y(n5) );
  NOR2XL U17 ( .A(n4), .B(n5), .Y(branch) );
  NOR2XL U18 ( .A(instn_30_), .B(instn_28_), .Y(n2) );
  NOR2XL U19 ( .A(instn_27_), .B(instn_31_), .Y(n1) );
  NAND4XL U20 ( .A(n2), .B(instn_26_), .C(n1), .D(n7), .Y(n9) );
  NAND2BXL U21 ( .AN(branch), .B(n9), .Y(ALUOp[0]) );
  NOR2XL U22 ( .A(instn_28_), .B(n5), .Y(RegDst) );
  NOR2XL U23 ( .A(instn_29_), .B(n10), .Y(MemtoReg) );
  NAND2XL U24 ( .A(state[0]), .B(PCSrc), .Y(n3) );
  NOR2XL U25 ( .A(state[1]), .B(n3), .Y(next_state[1]) );
  OR2X1 U26 ( .A(next_state[0]), .B(next_state[1]), .Y(beq_enable) );
  INVXL U27 ( .A(RegDst), .Y(n6) );
  NAND3BXL U28 ( .AN(MemtoReg), .B(n6), .C(n9), .Y(ALUOp[1]) );
  OR2XL U29 ( .A(n11), .B(ALUOp[1]), .Y(RegWrite) );
  NAND3BXL U30 ( .AN(n11), .B(n10), .C(n9), .Y(ALUSrc) );
endmodule


